import time
from confluent_kafka import KafkaError,KafkaException,TopicPartition

def replay(reader,topic,partitions,start_ms,end_ms):
    if type(start_ms) is not int or type(end_ms) is not int or start_ms<0 or end_ms<=start_ms:raise ValueError('finite nonempty time interval required')
    if not partitions or len(partitions)!=len(set(partitions)) or any(type(p) is not int or p<0 for p in partitions):raise ValueError('distinct nonnegative partitions required')
    bounds={p:reader.get_watermark_offsets(TopicPartition(topic,p),timeout=4,cached=False) for p in partitions}
    starts={row.partition:row.offset for row in reader.offsets_for_times([TopicPartition(topic,p,start_ms) for p in partitions],timeout=4)}
    result=[]
    for partition in sorted(partitions):
        low,limit=bounds[partition];begin=starts[partition]
        if begin<0 or begin>=limit:continue
        reader.assign([TopicPartition(topic,partition,max(low,begin))])
        deadline=time.monotonic()+8
        while time.monotonic()<deadline:
            message=reader.poll(.05)
            if message is None:continue
            if message.error():
                if message.error().code()==KafkaError._PARTITION_EOF and message.offset()>=limit:break
                raise KafkaException(message.error())
            if message.offset()>=limit:break
            kind,stamp=message.timestamp()
            if kind<0:raise ValueError('record timestamp unavailable')
            if start_ms<=stamp<end_ms:result.append({'partition':partition,'offset':message.offset(),'timestamp':stamp,'value':message.value()})
            if message.offset()+1>=limit:break
        else:raise TimeoutError('bounded retained log did not finish')
    return result
```

原题知识说明：
按指定时间查每分区候选offset，并核对记录时间戳类型、时钟与迟到事件。实际消费时再按业务时间过滤，保存起止水位；不能把全主题视为单一严格时间序列。

